import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type DonutChartAnimationProps = Record<string, any>;

const DonutItem: React.FC<{
  value: number;
  color: string;
  text: string;
  delay: number;
  textColor: string;
}> = ({ value, color, text, delay, textColor }) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Animation drivers
  const entrance = spring({
    frame: frame - delay,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const progress = spring({
    frame: frame - delay - 10,
    fps,
    config: { damping: 20, stiffness: 60 },
  });
  
  const textOpacity = interpolate(frame - delay - 20, [0, 15], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const textTranslate = interpolate(frame - delay - 20, [0, 15], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Donut calculations
  const radius = 90; // SVG coordinate space
  const strokeWidth = 35;
  const normalizedRadius = radius - strokeWidth / 2;
  const circumference = normalizedRadius * 2 * Math.PI;
  
  // Animate the stroke offset based on value
  // Ensure strict monotonicity for interpolate input is not needed here as we use progress directly
  const strokeDashoffset = circumference - (Math.min(progress, 1) * (value / 100)) * circumference;

  // Counter logic
  const displayValue = Math.round(Math.min(progress, 1) * value);

  // Responsive sizing based on standard 1920 width
  const scaleFactor = width / 1920; 

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        flex: 1,
        transform: `scale(${entrance})`,
        opacity: Math.min(1, entrance * 2), // Fade in quickly
      }}
    >
      {/* Donut Circle */}
      <div style={{ position: "relative", width: 300 * scaleFactor, height: 300 * scaleFactor }}>
        <svg
          height="100%"
          width="100%"
          viewBox={`0 0 ${radius * 2} ${radius * 2}`}
          style={{ transform: "rotate(-90deg)" }}
        >
          {/* Background Circle */}
          <circle
            stroke="white"
            strokeWidth={strokeWidth}
            fill="transparent"
            r={normalizedRadius}
            cx={radius}
            cy={radius}
          />
          {/* Progress Circle */}
          <circle
            stroke={color}
            strokeWidth={strokeWidth}
            strokeDasharray={`${circumference} ${circumference}`}
            style={{ strokeDashoffset }}
            strokeLinecap="butt"
            fill="transparent"
            r={normalizedRadius}
            cx={radius}
            cy={radius}
          />
        </svg>
        
        {/* Percentage Text Centered */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            fontSize: 50 * scaleFactor,
            fontWeight: 700,
            color: textColor,
            fontFamily: "Montserrat",
          }}
        >
          {displayValue}%
        </div>
      </div>

      {/* Colored Bar */}
      <div
        style={{
          width: 120 * scaleFactor,
          height: 15 * scaleFactor,
          backgroundColor: color,
          marginTop: 30 * scaleFactor,
          marginBottom: 30 * scaleFactor,
          transform: `scaleX(${progress})`,
        }}
      />

      {/* Description Text */}
      <div
        style={{
          opacity: textOpacity,
          transform: `translateY(${textTranslate}px)`,
          color: textColor,
          fontFamily: "Montserrat",
          fontSize: 22 * scaleFactor,
          lineHeight: 1.4,
          textAlign: "center",
          maxWidth: "80%",
          fontWeight: 600,
        }}
      >
        {text}
      </div>
    </div>
  );
};

